package com.abyssredemption.abstool.client.serverstats.network.payload;
import java.util.*; import net.minecraft.network.RegistryFriendlyByteBuf; import net.minecraft.network.codec.StreamCodec; import net.minecraft.network.protocol.common.custom.CustomPacketPayload; import net.minecraft.resources.Identifier;
public record LeaderboardResponsePayload(int protocolVersion,long requestId,int leaderboardType,int page,int totalPages,int totalEntries,long generatedAtEpochMillis,String contextLabel,List<Entry> entries) implements CustomPacketPayload {
 public record Entry(int rank,UUID uuid,String playerName,long value,boolean online) {}
 public static final Type<LeaderboardResponsePayload> TYPE=new Type<>(Identifier.fromNamespaceAndPath("absservertool","leaderboard_response"));
 public static final StreamCodec<RegistryFriendlyByteBuf,LeaderboardResponsePayload> CODEC=StreamCodec.of((b,p)->{b.writeVarInt(p.protocolVersion);b.writeVarLong(p.requestId);b.writeVarInt(p.leaderboardType);b.writeVarInt(p.page);b.writeVarInt(p.totalPages);b.writeVarInt(p.totalEntries);b.writeLong(p.generatedAtEpochMillis);b.writeUtf(p.contextLabel,128);b.writeVarInt(p.entries.size());for(var e:p.entries){b.writeVarInt(e.rank);b.writeUUID(e.uuid);b.writeUtf(e.playerName,64);b.writeVarLong(e.value);b.writeBoolean(e.online);}},b->{int v=b.readVarInt();long r=b.readVarLong();int t=b.readVarInt();int p=b.readVarInt();int tp=b.readVarInt();int te=b.readVarInt();long g=b.readLong();String c=b.readUtf(128);int n=b.readVarInt();if(n<0||n>100)throw new IllegalArgumentException("Invalid leaderboard entry count: "+n);List<Entry> es=new ArrayList<>(n);for(int i=0;i<n;i++)es.add(new Entry(b.readVarInt(),b.readUUID(),b.readUtf(64),b.readVarLong(),b.readBoolean()));return new LeaderboardResponsePayload(v,r,t,p,tp,te,g,c,List.copyOf(es));}); public Type<? extends CustomPacketPayload> type(){return TYPE;}
}
